def solve(grid):
    # Collect non-zero values with their column positions
    values = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                values.append((c, grid[r][c]))

    # Sort by column
    values.sort(key=lambda x: x[0])
    vals = [v[1] for v in values]

    # Pad to 9
    while len(vals) < 9:
        vals.append(0)

    # Fill 3x3 in boustrophedon order
    result = [[0]*3 for _ in range(3)]
    idx = 0
    for r in range(3):
        row_vals = vals[idx:idx+3]
        if r % 2 == 1:
            row_vals = row_vals[::-1]
        result[r] = row_vals
        idx += 3

    return result
